            mp_state.thermal_cycles = 0;
            mp_state.recovery_count = 0;
            mp_state.mode = MP_IDLE;
        }
    }
}

adcs_vec3_t realized_cmd = {0, 0, 0};
adcs_vec3_t captured_quant = {0, 0, 0};
int emit_zero_this_call = 0;

switch (mp_state.mode) {
    case MP_IDLE: {
        double start_th = mp_config.start_fraction * mp_config.max_dipole_a_m2;
        double stop_th = mp_config.stop_fraction * mp_config.max_dipole_a_m2;
        double req_vals[3] = {mp_input.request_a_m2->x, mp_input.request_a_m2->y, mp_input.request_a_m2->z};
        double last_vals[3] = {mp_state.last_capture_a_m2.x, mp_state.last_capture_a_m2.y, mp_state.last_capture_a_m2.z};

        // Quantize
        for (int i = 0; i < 3; ++i) {
            double threshold = start_th;
            if (last_vals[i] != 0.0) {
                if ((req_vals[i] > 0 && last_vals[i] > 0) || (req_vals[i] < 0 && last_vals[i] < 0)) {
                    threshold = stop_th;
                }
            }

            if (fabs(req_vals[i]) >= threshold) {
                if (i == 0) captured_quant.x = copysign(1.0, req_vals[i]) * mp_config.max_dipole_a_m2;
                else if (i == 1) captured_quant.y = copysign(1.0, req_vals[i]) * mp_config.max_dipole_a_m2;
                else if (i == 2) captured_quant.z = copysign(1.0, req_vals[i]) * mp_config.max_dipole_a_m2;
            }
        }

        // Check if all requests fall below stop threshold
        int all_below_stop = 1;
        for (int i = 0; i < 3; ++i) {
            if (fabs(req_vals[i]) >= stop_th) {
                all_below_stop = 0;
                break;
            }
        }

        if (all_below_stop) {
            mp_state.mode = MP_COOLDOWN;
            mp_state.elapsed = 0;
        } else {
            // Check reversal
            double dot = adcs_vec3_dot(&captured_quant, &mp_state.last_capture_a_m2);
            int last_was_nonzero = (mp_state.last_capture_a_m2.x != 0 || 
                                    mp_state.last_capture_a_m2.y != 0 || 
                                    mp_state.last_capture_a_m2.z != 0);

            if (last_was_nonzero && dot < 0) {
                 mp_state.mode = MP_REVERSAL_WAIT;
                 mp_state.elapsed = 0;
            } else {
                 mp_state.mode = MP_PULSE;
                 mp_state.captured_a_m2 = captured_quant;
                 mp_state.elapsed = 1;

                 // Handle Thermal Limit for Cycle 1
                 if (mp_state.thermal_cycles + 1 >= mp_config.max_thermal_cycles) {
                     emit_zero_this_call = 1;
                     mp_state.thermal_cycles++; // Reach max
                     mp_state.mode = MP_INHIBIT;
                     mp_state.recovery_count = 0;
                 } else {
                     mp_state.thermal_cycles++;
                 }
            }
        }
        break;
    }

    case MP_PULSE: {
        // Handle Thermal Limit for subsequent cycles
        if (mp_state.thermal_cycles + 1 >= mp_config.max_thermal_cycles) {
             emit_zero_this_call = 1;
             mp_state.thermal_cycles++;
             mp_state.mode = MP_INHIBIT;
             mp_state.recovery_count = 0;
        } else {
             mp_state.thermal_cycles++;
             realized_cmd = mp_state.captured_a_m2;
        }

        mp_state.elapsed++;

        if (emit_zero_this_call) {
             // Already handled mode change above, just ensure output is zero
             realized_cmd = (adcs_vec3_t){0, 0, 0};
        } else if (mp_state.elapsed >= mp_config.pulse_cycles) {
             mp_state.mode = MP_COOLDOWN;
             mp_state.elapsed = 0;
             mp_state.last_capture_a_m2 = mp_state.captured_a_m2;
        }
        break;
    }

    case MP_REVERSAL_WAIT: {
        realized_cmd = (adcs_vec3_t){0, 0, 0};
        mp_state.elapsed++;
        if (mp_state.elapsed >= mp_config.reversal_blank_cycles) {
            mp_state.mode = MP_IDLE;
            mp_state.elapsed = 0;
            mp_state.last_capture_a_m2.x = 0.0;
            mp_state.last_capture_a_m2.y = 0.0;
            mp_state.last_capture_a_m2.z = 0.0;
        }
        break;
    }

    case MP_COOLDOWN: {
        realized_cmd = (adcs_vec3_t){0, 0, 0};
        mp_state.elapsed++;
        if (mp_state.elapsed >= mp_config.cooldown_cycles) {
            mp_state.mode = MP_IDLE;
            mp_state.elapsed = 0;
        }
        break;
    }

    default:
        break;
}

// Calculate Torque based on realized command
adcs_vec3_t torque = adcs_vec3_cross(&realized_cmd, mp_input.field_body_t);

// Output assignment
mp_output.mode = mp_state.mode;
mp_output.elapsed = mp_state.elapsed;
mp_output.thermal_cycles = mp_state.thermal_cycles;
mp_output.recovery_count = mp_state.recovery_count;
mp_output.realized_a_m2 = realized_cmd;
mp_output.torque_nm = torque;

