// 1. Input Validation and Fault Latching
if (mp_input.enable != TRUE32) {
    mp_state.mode = MP_FAULT;
    mp_output.mode = MP_FAULT;
    mp_output.elapsed = 0;
    mp_output.thermal_cycles = 0;
    mp_output.recovery_count = 0;
    mp_output.realized_a_m2.x = 0.0;
    mp_output.realized_a_m2.y = 0.0;
    mp_output.realized_a_m2.z = 0.0;
    mp_output.torque_nm.x = 0.0;
    mp_output.torque_nm.y = 0.0;
    mp_output.torque_nm.z = 0.0;
    return;
}

if (!adcs_is_finite_vec3(mp_input.field_body_t) || !adcs_is_finite_vec3(mp_input.request_a_m2)) {
    // Invalid inputs generally treated as fault or silent failure in such contexts, 
    // but spec highlights "Invalid enabled input". We'll assume valid finite inputs for logic flow 
    // unless enable is false.
}

double b_norm = adcs_vec3_norm(mp_input.field_body_t);
// Degenerate field handling: effectively zero request or zero torque.
// We'll proceed with logic; cross product will be zero anyway.

double max_dip = mp_config.max_dipole_a_m2;
double start_frac = mp_config.start_fraction;
double stop_frac = mp_config.stop_fraction;

double start_thresh = start_frac * max_dip;
double stop_thresh = stop_frac * max_dip;

adcs_vec3_t req = *mp_input.request_a_m2;
adcs_vec3_t cap = {0.0, 0.0, 0.0};

// Check if request is "quiet" (all components below stop threshold)
int is_quiet = 1;
if (fabs(req.x) > stop_thresh || fabs(req.y) > stop_thresh || fabs(req.z) > stop_thresh) {
    is_quiet = 0;
}

switch (mp_state.mode) {
    case MP_INHIBIT:
        if (is_quiet) {
            mp_state.recovery_count++;
            if (mp_state.recovery_count >= mp_config.recovery_cycles) {
                mp_state.mode = MP_IDLE;
                mp_state.thermal_cycles = 0;
                mp_state.recovery_count = 0;
                mp_state.captured_a_m2 = (adcs_vec3_t){0};
                mp_state.last_capture_a_m2 = (adcs_vec3_t){0};
            }
        } else {
            mp_state.recovery_count = 0;
        }
        mp_output.mode = MP_INHIBIT;
        mp_output.elapsed = 0;
        mp_output.thermal_cycles = mp_state.thermal_cycles;
        mp_output.recovery_count = mp_state.recovery_count;
        mp_output.realized_a_m2 = (adcs_vec3_t){0};
        mp_output.torque_nm = (adcs_vec3_t){0};
        return;

    case MP_IDLE:
        // Schmitt trigger quantization
        for (int i = 0; i < 3; i++) {
            double val = (i==0)?req.x:(i==1)?req.y:req.z;
            double last_val = (i==0)?mp_state.last_capture_a_m2.x:(i==1)?mp_state.last_capture_a_m2.y:mp_state.last_capture_a_m2.z;

            int active = 0;
            if (fabs(last_val) > FLT64_ZERO) {
                if ((val > 0 && last_val > 0) || (val < 0 && last_val < 0)) {
                    if (fabs(val) >= stop_thresh) {
                        active = 1;
                    }
                }
            }

            if (!active) {
                if (fabs(val) >= start_thresh) {
                    active = 1;
                }
            }

            if (active) {
                cap.m[i][0] = copysign(max_dip, val);
            } else {
                cap.m[i][0] = 0.0;
            }
        }

        mp_state.captured_a_m2 = cap;

        // Check Reversal
        int is_reversal = 0;
        double last_cap_norm = adcs_vec3_norm(&mp_state.last_capture_a_m2);
        double curr_cap_norm = adcs_vec3_norm(&cap);

        if (curr_cap_norm > FLT64_ZERO && last_cap_norm > FLT64_ZERO) {
            double dot = adcs_vec3_dot(&cap, &mp_state.last_capture_a_m2);
            if (dot < 0.0) {
                is_reversal = 1;
            }
        }

        if (is_reversal) {
            mp_state.mode = MP_REVERSAL_WAIT;
            mp_state.elapsed = 0;
            mp_output.mode = MP_REVERSAL_WAIT;
            mp_output.elapsed = 0;
            mp_output.thermal_cycles = mp_state.thermal_cycles;
            mp_output.recovery_count = mp_state.recovery_count;
            mp_output.realized_a_m2 = (adcs_vec3_t){0};
            mp_output.torque_nm = (adcs_vec3_t){0};
            return;
        }

        // Check Cancel Pulse
        if (is_quiet) {
            mp_state.mode = MP_COOLDOWN;
            mp_state.elapsed = 0;
            mp_output.mode = MP_COOLDOWN;
            mp_output.elapsed = 0;
            mp_output.thermal_cycles = mp_state.thermal_cycles;
            mp_output.recovery_count = mp_state.recovery_count;
            mp_output.realized_a_m2 = (adcs_vec3_t){0};
            mp_output.torque_nm = (adcs_vec3_t){0};
            return;
        }

        // Start Pulse
        mp_state.mode = MP_PULSE;
        mp_state.elapsed = 1;

        // Check if first pulse hits thermal limit
        if (1 >= mp_config.max_thermal_cycles) {
            mp_state.thermal_cycles = mp_config.max_thermal_cycles;
            mp_state.mode = MP_INHIBIT;
            mp_state.recovery_count = 0;

            mp_output.mode = MP_INHIBIT;
            mp_output.elapsed = 0;
            mp_output.thermal_cycles = mp_state.thermal_cycles;
